import { describe, it, expect } from 'vitest'
import { shapesOf, identicalShapes, subsets } from './index'

/**
 * Measured against the LIVE config (payload-types is generated BY Payload — the shapes it actually booted).
 * Not fixtures: the finding IS the live tree, and a fixture would only prove the algorithm.
 */
describe('collapse — what can honestly become one table', () => {
  it('reads every booted collection from the generated types', () => {
    const s = shapesOf()
    expect(s.length).toBeGreaterThan(200)
    expect(s.map((x) => x.slug)).toContain('gl-postings')
  })

  // THE REFUTATION OF THE TELOS. "Collapse ~200 collections to a dense core" implies redundancy.
  // Content-addressing says there is none: 231 genuinely distinct shapes, zero duplicates.
  it('NO two collections are the same table — structural headroom is zero', () => {
    expect(identicalShapes()).toHaveLength(0)
  })

  it('the shape address is a theorem — same fields+types ⇒ same uuid', () => {
    const s = shapesOf()
    const uniq = new Set(s.map((x) => x.uuid))
    expect(uniq.size).toBe(s.length) // 231 distinct shapes ⇒ 231 distinct addresses
    expect(s[0]!.uuid).toHaveLength(36)
  })

  // THE ONE REAL MERGE, and it is exact: not "similar", not "both are parties" — one field.
  it('customers ⊂ vendors, differing by exactly `bank` — the only semantically real subset', () => {
    const party = subsets().find((s) => s.slug === 'customers' && s.host === 'vendors')
    expect(party).toBeDefined()
    expect(party!.extra).toEqual(['bank'])
  })

  // THE BOUNDARY, asserted rather than promised. Set inclusion is DECIDABLE and decides the WRONG question:
  // a small table fits inside almost anything. This is where "trust only theorems" stops — a theorem cannot
  // tell you what two tables MEAN.
  it('fitting is NOT sameness — the tool proposes absurd merges, and must be read by a human', () => {
    const all = subsets()
    const absurd = all.find((s) => s.slug === 'payload-migrations')
    expect(absurd).toBeDefined() // Payload's OWN migration table "fits" inside a manufacturing table
    expect(absurd!.extra.length).toBeGreaterThan(20) // 22 fields apart: fitting, and meaning nothing
    // the real one sorts FIRST: fewest extra fields = closest to sameness
    expect(all[0]!.slug).toBe('customers')
  })
})
